/**
 * GitHub REST API, through the connection's Named Credential (default RLY_GitHub, URL https://api.github.com).
 * Token: fine-grained, one repository, Actions: read and write, Pull requests and Metadata: read,
 * Contents: read (or read and write to edit files from Salesforce and sync back to the source org).
 */
public with sharing class RlyGitHubService extends RlyGitProvider {

    private static final Pattern REPO_PATTERN = Pattern.compile('^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$');
    private static final Map<String, String> HEADERS = new Map<String, String>{
        'Accept' => 'application/vnd.github+json', 'X-GitHub-Api-Version' => '2022-11-28'
    };

    private String repo;
    private String owner;
    private final Map<String, List<Object>> contentsCache = new Map<String, List<Object>>();

    protected override void init(RlySettings.Connection c) {
        super.init(c);
        this.repo = c.repository.trim();
        this.owner = this.repo.substringBefore('/');
    }

    public override Pattern repositoryPattern() { return REPO_PATTERN; }
    public override String repositoryHint() { return 'owner/repo'; }

    public override Boolean branchExists(String branch) {
        HttpResponse res = send('GET', '/repos/' + repo + '/branches/' + RlyGitProvider.enc(branch), null, HEADERS);
        if (res.getStatusCode() == 404) {
            return false;
        }
        assertOk(res, 'Branch lookup');
        return true;
    }

    public override List<String> listBranches() {
        List<String> names = new List<String>();
        for (Integer page = 1; page <= 3; page++) {
            HttpResponse res = send('GET', '/repos/' + repo + '/branches?per_page=100&page=' + page, null, HEADERS);
            assertOk(res, 'Branch list');
            List<Object> rows = (List<Object>) RlyGitProvider.parse(res);
            for (Object o : rows) {
                names.add(String.valueOf(((Map<String, Object>) o).get('name')));
            }
            if (rows.size() < 100) {
                break;
            }
        }
        return names;
    }

    public override String getFileRaw(String filePath, String ref) {
        HttpResponse res = send('GET', '/repos/' + repo + '/contents/' + RlyGitProvider.encPath(filePath) + '?ref=' + RlyGitProvider.enc(ref), null,
            new Map<String, String>{ 'Accept' => 'application/vnd.github.raw+json', 'X-GitHub-Api-Version' => '2022-11-28' });
        if (res.getStatusCode() == 404) {
            return null;
        }
        assertOk(res, 'File read');
        return res.getBody();
    }

    /** Uses the folder's tree, so folders with more than 1,000 entries are listed in full. */
    public override List<Entry> listDir(String folderPath, String ref) {
        String parent = folderPath.contains('/') ? folderPath.substringBeforeLast('/') : '';
        String name = folderPath.contains('/') ? folderPath.substringAfterLast('/') : folderPath;
        String sha;
        for (Object o : contents(parent, ref)) {
            Map<String, Object> m = (Map<String, Object>) o;
            if (m.get('name') == name && m.get('type') == 'dir') {
                sha = String.valueOf(m.get('sha'));
            }
        }
        List<Entry> out = new List<Entry>();
        if (sha == null) {
            return out;
        }
        HttpResponse res = send('GET', '/repos/' + repo + '/git/trees/' + RlyGitProvider.enc(sha), null, HEADERS);
        assertOk(res, 'Folder read');
        for (Object o : (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('tree')) {
            Map<String, Object> m = (Map<String, Object>) o;
            out.add(RlyGitProvider.entry(String.valueOf(m.get('path')), m.get('type') == 'tree'));
        }
        return out;
    }

    /** One recursive tree read: every file path in the branch with its blob hash. Null when too large. */
    public override Map<String, String> treeShas(String ref) {
        HttpResponse res = send('GET', '/repos/' + repo + '/git/trees/' + RlyGitProvider.enc(ref) + '?recursive=1', null, HEADERS);
        if (res.getStatusCode() == 404) {
            return new Map<String, String>();
        }
        assertOk(res, 'Branch read');
        if (res.getBody().length() > 3000000) {
            return null; // very large repositories: use folder listings instead
        }
        Map<String, Object> body = (Map<String, Object>) RlyGitProvider.parse(res);
        if (body.get('truncated') == true) {
            return null;
        }
        Map<String, String> out = new Map<String, String>();
        for (Object o : (List<Object>) body.get('tree')) {
            Map<String, Object> m = (Map<String, Object>) o;
            if (m.get('type') == 'blob') {
                out.put(String.valueOf(m.get('path')), String.valueOf(m.get('sha')));
            }
        }
        return out;
    }

    private List<Object> contents(String folderPath, String ref) {
        String key = ref + '|' + folderPath;
        if (!contentsCache.containsKey(key)) {
            HttpResponse res = send('GET', '/repos/' + repo + '/contents/' + RlyGitProvider.encPath(folderPath) + '?ref=' + RlyGitProvider.enc(ref), null, HEADERS);
            if (res.getStatusCode() == 404) {
                contentsCache.put(key, new List<Object>());
            } else {
                assertOk(res, 'Folder read');
                Object body = RlyGitProvider.parse(res);
                contentsCache.put(key, body instanceof List<Object> ? (List<Object>) body : new List<Object>());
            }
        }
        return contentsCache.get(key);
    }

    public override Comparison compare(String baseRef, String head) {
        HttpResponse res = send('GET', '/repos/' + repo + '/compare/' + RlyGitProvider.enc(baseRef) + '...' + RlyGitProvider.enc(head) + '?per_page=100', null, HEADERS);
        if (res.getStatusCode() == 404) {
            throw new GitException('Branch ' + head + ' or ' + baseRef + ' was not found.');
        }
        assertOk(res, 'Compare');
        Map<String, Object> body = (Map<String, Object>) RlyGitProvider.parse(res);
        Comparison c = new Comparison();
        c.aheadBy = RlyGitProvider.toInt(body.get('ahead_by'));
        c.behindBy = RlyGitProvider.toInt(body.get('behind_by'));
        c.url = String.valueOf(body.get('html_url'));
        List<Object> files = (List<Object>) body.get('files');
        if (files != null) {
            for (Object o : files) {
                Map<String, Object> f = (Map<String, Object>) o;
                c.files.add(String.valueOf(f.get('status')) + '  ' + String.valueOf(f.get('filename')));
            }
        }
        return c;
    }

    /** GitHub answers 204 with no run id; the run is found later by its name, which carries the release number. */
    public override Started startPipeline(Map<String, String> inputs) {
        Map<String, Object> body = new Map<String, Object>{ 'ref' => conn.workflowRef, 'inputs' => inputs };
        HttpResponse res = send('POST', '/repos/' + repo + '/actions/workflows/' + RlyGitProvider.enc(conn.workflowFile) + '/dispatches',
            JSON.serialize(body), HEADERS);
        assertOk(res, 'Workflow start');
        return new Started();
    }

    public override Run findRun(String releaseName, String runMode, String knownRunId) {
        HttpResponse res = send('GET', '/repos/' + repo + '/actions/workflows/' + RlyGitProvider.enc(conn.workflowFile)
            + '/runs?event=workflow_dispatch&per_page=50', null, HEADERS);
        assertOk(res, 'Workflow run lookup');
        for (Object o : (List<Object>) ((Map<String, Object>) RlyGitProvider.parse(res)).get('workflow_runs')) {
            Map<String, Object> r = (Map<String, Object>) o;
            String title = String.valueOf(r.get('display_title'));
            if (title != null && title.contains(releaseName + ' ') && (runMode == null || title.contains('(' + runMode + ')'))) {
                Run run = new Run();
                run.id = String.valueOf(r.get('id'));
                run.status = String.valueOf(r.get('status')) == 'completed' ? 'completed'
                    : String.valueOf(r.get('status')) == 'in_progress' ? 'in_progress' : 'queued';
                String conclusion = r.get('conclusion') == null ? null : String.valueOf(r.get('conclusion'));
                run.conclusion = conclusion == null ? null : conclusion == 'success' ? 'success'
                    : conclusion == 'cancelled' ? 'cancelled' : 'failure';
                run.url = String.valueOf(r.get('html_url'));
                run.createdAt = RlyGitProvider.parseTime(r.get('created_at'));
                return run;
            }
        }
        return null;
    }

    public override Boolean canWrite() {
        return true;
    }

    /** Contents API: reads the file's blob sha on the branch (if it exists), then writes the new text as a commit. */
    public override void saveFile(String filePath, String branch, String content, String message) {
        String path = '/repos/' + repo + '/contents/' + RlyGitProvider.encPath(filePath);
        HttpResponse cur = send('GET', path + '?ref=' + RlyGitProvider.enc(branch), null, HEADERS);
        String sha;
        if (cur.getStatusCode() != 404) {
            assertOk(cur, 'File read');
            Object body = RlyGitProvider.parse(cur);
            if (body instanceof Map<String, Object>) {
                sha = String.valueOf(((Map<String, Object>) body).get('sha'));
            }
        }
        Map<String, Object> req = new Map<String, Object>{
            'message' => message,
            'branch' => branch,
            'content' => EncodingUtil.base64Encode(Blob.valueOf(content == null ? '' : content))
        };
        if (sha != null) {
            req.put('sha', sha);
        }
        HttpResponse res = send('PUT', path, JSON.serialize(req), HEADERS);
        if (res.getStatusCode() == 403 || res.getStatusCode() == 404) {
            throw new GitException('GitHub refused the save (HTTP ' + res.getStatusCode() + '). The token in ' + conn.namedCredential
                + ' needs Contents: Read and write on ' + repo + '.');
        }
        assertOk(res, 'File save');
    }

    public override void createBranch(String branch, String fromRef) {
        HttpResponse ref = send('GET', '/repos/' + repo + '/git/ref/heads/' + RlyGitProvider.encPath(fromRef), null, HEADERS);
        if (ref.getStatusCode() == 404) {
            throw new GitException('Branch ' + fromRef + ' wasn\'t found in ' + repo + '.');
        }
        assertOk(ref, 'Branch lookup');
        Map<String, Object> target = (Map<String, Object>) ((Map<String, Object>) RlyGitProvider.parse(ref)).get('object');
        Map<String, Object> body = new Map<String, Object>{ 'ref' => 'refs/heads/' + branch, 'sha' => String.valueOf(target.get('sha')) };
        HttpResponse res = send('POST', '/repos/' + repo + '/git/refs', JSON.serialize(body), HEADERS);
        if (res.getStatusCode() == 403 || res.getStatusCode() == 404) {
            throw new GitException('GitHub refused to create branch ' + branch + ' (HTTP ' + res.getStatusCode() + '). The token in '
                + conn.namedCredential + ' needs Contents: Read and write on ' + repo + '.');
        }
        assertOk(res, 'Branch create');
    }

    public override PullRequest findPullRequest(String branch, String target) {
        HttpResponse res = send('GET', '/repos/' + repo + '/pulls?state=all&per_page=1&head=' + RlyGitProvider.enc(owner + ':' + branch)
            + '&base=' + RlyGitProvider.enc(target), null, HEADERS);
        assertOk(res, 'Pull request lookup');
        List<Object> rows = (List<Object>) RlyGitProvider.parse(res);
        if (rows.isEmpty()) {
            return null;
        }
        Map<String, Object> m = (Map<String, Object>) rows[0];
        PullRequest pr = new PullRequest();
        pr.num = RlyGitProvider.toInt(m.get('number'));
        pr.url = String.valueOf(m.get('html_url'));
        pr.state = String.valueOf(m.get('state')) == 'open' ? 'open' : 'closed';
        pr.merged = m.get('merged_at') != null;
        return pr;
    }

    public override List<PrFile> pullFiles(Integer prNumber, String target, String branch) {
        List<PrFile> out = new List<PrFile>();
        Integer budget = 2000000;
        for (Integer page = 1; page <= 3; page++) {
            HttpResponse res = send('GET', '/repos/' + repo + '/pulls/' + prNumber + '/files?per_page=100&page=' + page, null, HEADERS);
            assertOk(res, 'Pull request files');
            List<Object> rows = (List<Object>) RlyGitProvider.parse(res);
            for (Object o : rows) {
                Map<String, Object> m = (Map<String, Object>) o;
                PrFile f = new PrFile();
                f.filename = String.valueOf(m.get('filename'));
                f.status = String.valueOf(m.get('status'));
                f.additions = RlyGitProvider.toInt(m.get('additions'));
                f.deletions = RlyGitProvider.toInt(m.get('deletions'));
                budget = RlyGitProvider.fitPatch(f, m.get('patch') == null ? '' : String.valueOf(m.get('patch')), budget);
                out.add(f);
            }
            if (rows.size() < 100) {
                break;
            }
        }
        return out;
    }
}
